-- ============ grammar_meanings ============

-- 35 ～ように／～ような
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ee7e301d-9344-507b-925b-95e909465bd7', 0, 'Biểu thị ví dụ, cách làm tương tự — "như là ~".', ARRAY['ここに書いてあるように申込書に記入してください。','東京のように人口が集中すると、交通渋滞は避けられない。']::text[], ARRAY['Hãy điền vào đơn đăng ký như viết ở mẫu này.','Cứ tập trung dân số như ở Tokyo, khó mà tránh khỏi giao thông ùn tắc.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ee7e301d-9344-507b-925b-95e909465bd7', 1, 'Biểu thị mục tiêu, mong muốn đạt được — "để cho ~".', ARRAY['この本は小学生でも読めるようにルビがつけてあります。','予定通り終わるように計画を立ててやってください。']::text[], ARRAY['Cuốn sách này, để cho học sinh tiểu học cũng đọc được, phiên âm được đính vào.','Hãy lập kế hoạch để có thể kết thúc theo kế hoạch.']::text[]);

-- 36 ～一方だ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('74403438-1728-5da6-aae7-216051b284ab', 0, 'Diễn tả một xu hướng chỉ tiếp tục theo một chiều, ngày càng như vậy.', ARRAY['最近、パソコン通信の利用者は増える一方だ。','最近英語を使わないので、忘れる一方で困っている。']::text[], ARRAY['Gần đây người dùng máy tính để trao đổi thông tin ngày càng tăng lên.','Gần đây vì không sử dụng tiếng Anh, quên ngày càng nhiều, thật khổ.']::text[]);

-- 37 ～おそれがある
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('0dc53113-6a7c-5cce-b145-edae7f422710', 0, 'Có sự lo lắng, nguy cơ một điều không tốt sẽ xảy ra.', ARRAY['台風がこのまま北上すると、日本に上陸する恐れがある。','こんなに赤字が続くと、この会社は倒産の恐れがある。']::text[], ARRAY['Nếu bão vẫn cứ tiến theo hướng Bắc như thế này, có khả năng sẽ đổ bộ vào Nhật Bản.','Cứ tiếp tục thua lỗ như thế, công ty này có ngày phá sản.']::text[]);

-- 38 ～ことになっている
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('917cc76e-220b-5483-bb52-d0c164e256cd', 0, 'Biểu thị dự định, quy tắc, quy định đã được ấn định từ trước.', ARRAY['今度の日曜日には、友達と会うことになっています。','法律で、子供を働かせてはいけないことになっている。']::text[], ARRAY['Chủ nhật tới tôi định gặp mặt bạn bè.','Theo pháp luật, cấm bắt trẻ em phải lao động.']::text[]);

-- 39 ～ことはない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('62735d76-82f7-5e51-a68d-b559c3b527b9', 0, 'Không cần thiết phải làm việc đó.', ARRAY['時間は十分あるから、急ぐことはない。','検査の結果、異常ありませんでしたから心配することはありませんよ。']::text[], ARRAY['Vẫn có đủ thời gian, không cần phải vội.','Vì kết quả kiểm tra không có gì khác thường nên không cần lo lắng đâu.']::text[]);

-- 40 ～しかない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ed4c8c54-0f96-5d0c-8d1f-1c66a4904774', 0, 'Không có cách nào khác ngoài việc phải làm điều đó.', ARRAY['事故で電車が動かないから、歩いて行くしかない。','だれにも頼めないから、自分でやるしかありません。']::text[], ARRAY['Do tai nạn nên tàu không chạy, chẳng có cách nào khác là đi bộ.','Không nhờ ai được, tự mình phải làm thôi.']::text[]);

-- 41 ～ということだ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b5bf7b83-ce89-5b9e-a4bb-cff2490b208c', 0, 'Nghe nói là ~ — trích dẫn lại nguyên văn điều nghe được.', ARRAY['新聞によると、また地下鉄の運賃が値上げされるということだ。','天気予報によると今年は雨が多いだろうということです。']::text[], ARRAY['Theo báo nói, giá vé tàu điện ngầm lại bị tăng lên.','Nghe dự báo thời tiết thì năm nay mưa nhiều đấy.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b5bf7b83-ce89-5b9e-a4bb-cff2490b208c', 1, 'Có nghĩa là ~ — dùng để diễn giải lại ý vừa nghe/nói.', ARRAY['「あしたは、ちょっと忙しいんです。」「えっ。じゃ、パーティーには来られないということですか。」','ご意見がないということは賛成ということですね。']::text[], ARRAY['"Mai tớ bận tí." "Thế à. Thế nghĩa là không đến liên hoan à?"','Không có ý kiến gì tức là tán thành phải không ạ.']::text[]);

-- 42 ～まい／～まいか
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('9fad7ab0-1d4a-5af6-8365-914a013cad80', 0, 'Có lẽ sẽ không ~ — thể hiện suy đoán phủ định.', ARRAY['あの民族紛争は容易に解決するまいと思うが、平和的解決への努力が必要だ。','彼はベテランの登山家だから、あんな低い山で遭難することはあるまい。']::text[], ARRAY['Tôi nghĩ là cuộc phân tranh sắc tộc đó không dễ giải quyết nhưng những nỗ lực để giải quyết hòa bình là cần thiết.','Ông ấy là nhà leo núi nhiều kinh nghiệm nên việc gặp nạn trên núi thấp cỡ đó chắc là không có đâu.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('9fad7ab0-1d4a-5af6-8365-914a013cad80', 1, 'Tuyệt đối muốn từ bỏ việc ~ — chỉ ý chí phủ định, quyết không làm.', ARRAY['こんなまずいレストランへは二度と来るまい。','ケーキは買うまいと思っても、見るとつい買ってしまう。']::text[], ARRAY['Cái nhà hàng tồi cỡ này thì không muốn đến lần thứ hai.','Đã định không mua bánh ngọt rồi, nhìn thấy lại sơ ý mua mất.']::text[]);

-- 43 ～わけがない／～わけはない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('a639da1f-8b8f-5b2d-9751-786159697347', 0, 'Không có lý do/khả năng nào cho việc đó — khẳng định mạnh là không thể.', ARRAY['あんな下手な絵が売れるわけがない。','あんなやせた人が、相撲とりのわけがない。']::text[], ARRAY['Bức tranh tệ thế thì không chắc đã bán được.','Người gầy cỡ này thì không thể là lực sĩ Sumo được.']::text[]);

-- 44 ～わけにはいかない／～わけにもいかない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('256e8bf6-7e89-5cef-9b96-2ca27fcb4c93', 0, 'Có lý do (đạo đức, xã hội) nên không thể làm ~.', ARRAY['絶対にほかの人に言わないと約束したので、話すわけにはいかない。','帰りたいけれども、この論文が完成するまでは帰国するわけにはいかない。']::text[], ARRAY['Vì đã hứa là tuyệt đối không nói với người khác nên không thể kể được.','Dù muốn về nhưng đến khi hoàn thành luận văn này thì không về nước được.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('256e8bf6-7e89-5cef-9b96-2ca27fcb4c93', 1, 'Phải làm ~ — không thể không làm.', ARRAY['あした試験があるので、勉強しないわけにはいかない。','家族がいるから、働かないわけにはいかない。']::text[], ARRAY['Vì ngày mai có bài thi nên không thể không học được.','Vì có gia đình nên không đi làm không được.']::text[]);

-- 45 ～から～にかけて
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('81b0db01-98ae-5b1d-80c7-e5191aff4639', 0, 'Từ khoảng ~ đến ~, chỉ chung phạm vi thời gian hoặc địa điểm (không xác định mốc rõ rệt).', ARRAY['昨夜から今朝にかけて雨が降りました。','関東地方から東北地方にかけて、大きな地震があった。']::text[], ARRAY['Trời đã mưa từ đêm qua đến sáng nay.','Đã có động đất mạnh trong khu vực từ Kanto đến Tohoku.']::text[]);

-- 46 たとえ～ても／たとえ～でも
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('72fa61cf-d235-5ba7-9a95-783c9a4499a7', 0, 'Dù có ~ đi nữa thì vẫn ~, đưa ra giả định cực đoan.', ARRAY['自分で決めた道だから、たとえ失敗しても後悔しない。','この仕事は、たとえ困難でも最後まで頑張らなければならない。']::text[], ARRAY['Vì con đường đi do tôi tự quyết định nên nếu có thất bại thì cũng không hối tiếc.','Công việc này, dù cho có vất vả khó khăn, vẫn cần phải cố gắng đến cùng.']::text[]);

-- 47 ～さえ～ば
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('4486b45f-2f83-5c4e-bf43-1b73db957c34', 0, 'Chỉ cần có/thỏa mãn điều kiện đó là đủ để điều phía sau xảy ra.', ARRAY['インスタントラーメンはお湯を入れさえすれば食べられる便利な食品だ。','住所さえわかれば、地図で探していきます。']::text[], ARRAY['Mì ăn liền là thứ đồ ăn tiện lợi, chỉ cần cho nước nóng vào là ăn được.','Biết địa chỉ thì đi tìm bằng bản đồ ngay.']::text[]);

-- 48 ～も～ば～も／～も～なら～も
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('d3c375f5-c444-52a2-bdea-bc03fb182ab2', 0, 'Cũng ~ cũng ~, liệt kê thêm một điều cùng chiều hướng (cùng tốt hoặc cùng xấu) với điều vừa nói.', ARRAY['父はお酒も飲めばタバコも吸うので、健康が心配だ。','彼は歌も上手なら踊りもうまい、パーティーの人気者だ。']::text[], ARRAY['Bố rượu cũng uống, thuốc cũng hút, vì thế nên sức khỏe rất đáng lo.','Anh ấy hát cũng hay, nhảy cũng giỏi, rất được yêu mến ở buổi tiệc.']::text[]);

-- 49 ～やら～やら
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('792bbf45-d4ab-59a2-a63a-5e1830d763e1', 0, 'Liệt kê nhiều việc (nọ, kia...) gây cảm giác bề bộn, mệt mỏi.', ARRAY['帰国前は飛行機を予約するやらおみやげを買うやらで忙しい。','お酒を飲みすぎて、頭が痛いやら苦しいやらで、大変だった。']::text[], ARRAY['Trước khi về nước, tất bật với đặt vé máy bay, mua quà lưu niệm...','Uống quá nhiều rượu, đau đầu, mệt mỏi, đến là sợ.']::text[]);

-- 50 ～だらけ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('79dfd539-f264-59f6-b1c4-f0f3fd3bb1df', 0, 'Đầy ~, toàn là ~ (thứ bẩn, xấu, không mong muốn tràn lan khắp nơi).', ARRAY['このレポートは字が間違いだらけで読みにくい。','世界各地を旅行したので、私の旅行かばんはきずだらけだ。']::text[], ARRAY['Bản báo cáo này đầy chữ đánh nhầm, đọc khó.','Vì đi du lịch nhiều nơi trên thế giới nên vali du lịch của tôi đầy vết xước.']::text[]);

-- 51 ～っぽい
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b18dba91-a707-501d-9c7c-11545cc0d4f2', 0, 'Cảm thấy như là ~, trông có vẻ ~.', ARRAY['このテーブルは高いのに安っぽく見える。','あの子はまだ中学生なのに、とても大人っぽい。']::text[], ARRAY['Cái bàn này dù đắt nhưng nhìn rẻ tiền.','Thằng nhỏ đó tuy vẫn là học sinh trung học nhưng trông rất người lớn.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b18dba91-a707-501d-9c7c-11545cc0d4f2', 1, 'Dễ ~, hay có xu hướng ~.', ARRAY['彼は怒りっぽいけれど、本当は優しい人です。','最近忘れっぽくなったのは、年のせいだろう。']::text[], ARRAY['Anh ấy là người dễ nổi nóng nhưng thực ra là người rất hiền lành.','Gần đây mau quên thế là tại tuổi cao rồi chăng?']::text[]);

-- 52 ～がたい
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('87c3f6a3-91df-5663-92d5-4a49c80176ed', 0, 'Khó làm ~, gần như không thể ~ (về mặt tinh thần, cảm xúc).', ARRAY['彼女がそんなことをするとは、信じがたい。','幼い子供に対する犯罪は許しがたい。']::text[], ARRAY['Cô ấy đến việc đó mà cũng làm được, thật khó tin.','Tội phạm đối với trẻ nhỏ là không thể tha thứ được.']::text[]);

-- 53 ～がちだ／～がちの
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5f85e3b8-45e9-597a-a36e-c2e474a6655b', 0, 'Việc đó thường hay xảy ra, dễ nghiêng về xu hướng đó (thường mang nghĩa xấu).', ARRAY['雪が降ると、電車は遅れがちだ。','母は病気がちなので、あまり働けない。']::text[], ARRAY['Khi tuyết rơi, tàu thường hay trễ.','Mẹ hay ốm nên chẳng làm việc được mấy.']::text[]);

-- 54 ～気味
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5fb295b1-250c-5589-9d92-113a71996c03', 0, 'Hơi có cảm giác là ~, có chút thiên hướng ~ ngay lúc này.', ARRAY['仕事が忙しくて、最近少し疲れ気味だ。','[日本語能力試験]が近づいたので、焦り気味だ。']::text[], ARRAY['Vì công việc bận nên gần đây hơi thấy mệt.','Kỳ thi năng lực tiếng Nhật đã đến gần, tôi thấy hơi sốt ruột.']::text[]);

-- 55 ～げ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('3849c416-5eaa-53c3-85ef-3b00b31965ef', 0, 'Vẻ ~, trông có vẻ ~ (thể hiện tâm trạng cảm nhận được qua vẻ ngoài người khác).', ARRAY['彼女は悲しげな様子で話した。','彼は寂しげに、一人で公園のベンチに座っていた。']::text[], ARRAY['Cô ấy đã nói chuyện với dáng vẻ buồn thảm.','Anh ta ngồi một mình trên ghế đá công viên với vẻ khá cô đơn.']::text[]);

-- 56 ～かけだ／～かけの／～かける
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('140f881f-f9a7-5fc5-9e1d-d656a31326b3', 0, 'Chỉ trạng thái vừa mới bắt đầu, đang dang dở, chưa kết thúc.', ARRAY['この仕事はやりかけですから、そのままにしておいてください。','テーブルの上に飲みかけのコーヒーが置いてある。']::text[], ARRAY['Công việc này mới bắt đầu làm nên cứ để như thế.','Trên bàn có đặt một cốc cà phê uống dở.']::text[]);

-- 57 ～きる／～きれる／～きれない
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('7789a2ae-6ab9-5f87-b72b-5804d8b8d670', 0, 'Hoàn toàn, làm trọn vẹn hết; hoặc có thể/không thể làm hết đến cùng.', ARRAY['木村さんは疲れきった顔をして帰って来た。','そんなにたくさん食べきれますか。']::text[], ARRAY['Anh Kimura với bộ mặt mệt phờ đã về.','Ăn bao nhiêu hết sạch cả thế này à?']::text[]);

-- 58 ～ぬく
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('52481372-d585-571e-b6eb-92a9bb273562', 0, 'Cố gắng, kiên trì làm đến cùng một việc gian nan.', ARRAY['途中、失敗もありましたが、何とかこの仕事をやりぬくことができました。','これは考えぬいて、出した結論です。']::text[], ARRAY['Giữa chừng tuy cũng thất bại, nhưng dù thế nào thì công việc này đã được làm đến cùng.','Đây là kết luận rút ra sau khi đã suy nghĩ đến cùng.']::text[]);

-- 59 ～こそ／～からこそ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('8461602d-154e-5ec3-b1b8-c5f5019c8e69', 0, 'Thể hiện ý nhấn mạnh — "chính là ~", "chính vì ~".', ARRAY['今度こそ試合に勝ちたい。','あなたが手伝ってくれたからこそ、仕事が早くできたのです。']::text[], ARRAY['Muốn thắng trận trong chính năm nay.','Chính vì nhờ có anh giúp đỡ, công việc mới làm xong nhanh.']::text[]);

-- 60 ～さえ／～でさえ
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('77b4f91c-ed61-5c6a-a0ba-4642619e4072', 0, 'Cũng ~, ngay cả ~ — lấy một ví dụ cực đoan để ngầm khẳng định những trường hợp khác đương nhiên cũng vậy.', ARRAY['専門家でさえわからないのだから、私たちには無理でしょう。','私の故郷は地図にさえ書いてない小さな村です。']::text[], ARRAY['Đến chuyên gia còn không hiểu thì chúng ta chịu thôi.','Quê tôi là một làng nhỏ đến không cả có tên trên bản đồ.']::text[]);

-- 61 ～など／～なんか／～なんて
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ca07e76b-c745-54a5-be8a-efc20cbd1279', 0, 'Dùng khi nêu một ví dụ để làm nhẹ giọng, thân mật hơn.', ARRAY['「この機械に詳しい人はいませんか。」「彼など詳しいと思いますよ。」','お見舞いならカーネーションなんてどうかしら。']::text[], ARRAY['"Có ai biết tường tận về cái máy này không?" "Tôi nghĩ như anh ấy là người biết rõ đấy."','Đi thăm người ốm thì không biết mua hoa cẩm chướng có được không nhỉ.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ca07e76b-c745-54a5-be8a-efc20cbd1279', 1, 'Dùng khi nói mang tính phủ định hoặc coi nhẹ, đánh giá không quan trọng.', ARRAY['忙しくて、テレビなど見ていられない。','スキーなんて簡単ですよ。だれでもすぐできるようになります。']::text[], ARRAY['Bận ghê, đến như cả xem TV còn chẳng được.','Cỡ như trượt tuyết thì dễ không mà, ai cũng biết trượt tuyết ngay.']::text[]);

-- 62 ～に関して（は）／～に関しても／～に関する
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('4ff96bde-949b-55f7-bde5-62010d6f9679', 0, 'Liên quan đến, về vấn đề ~.', ARRAY['計画変更に関しては、十分検討する必要がある。','経済に関する本はたくさんある。']::text[], ARRAY['Cần phải kiểm tra kỹ càng về việc thay đổi kế hoạch.','Có rất nhiều sách liên quan đến kinh tế.']::text[]);

-- 63 ～に加えて／～に加え
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b3743175-3ba4-55f2-b20c-41584e7e80aa', 0, 'Ngoài ~ ra, thêm vào đó còn ~ (2 điều cùng cộng dồn tác động).', ARRAY['電気代に加えて、ガス代までが値上がりした。','大気汚染が進んでいることに加え、海洋汚染も深刻化してきた。']::text[], ARRAY['Giá điện rồi đến giá gas cũng tăng lên.','Thêm vào việc ô nhiễm không khí ngày càng tiếp diễn, ô nhiễm biển đã nghiêm trọng hơn.']::text[]);

-- 64 ～に答えて／～にこたえ／～にこたえる／～にこたえた
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('b9855857-1ce7-53fa-80e1-e1b739a31536', 0, 'Đáp ứng lại, hồi đáp với mong muốn/tác động từ bên ngoài.', ARRAY['社員の要求にこたえて、労働時間を短縮した。','国民の声にこたえた政策が期待されています。']::text[], ARRAY['Đáp ứng yêu cầu của nhân viên, thời gian làm việc đã được rút ngắn.','Một chính sách đáp ứng tiếng nói của nhân dân đang được kỳ vọng.']::text[]);

-- 65 ～に沿って／～に沿い／～に沿う／～に沿った
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('dcc94866-8278-5fbc-9e5b-45d458fab014', 0, 'Theo đúng ~, dựa theo phương châm, kế hoạch, mong muốn đã định.', ARRAY['決まった方針に沿って、新しい計画を立てましょう。','国益に沿った外交政策が進められている。']::text[], ARRAY['Theo phương châm đã quyết định, hãy lập kế hoạch mới.','Chính sách ngoại giao phù hợp với lợi ích quốc gia đang được áp dụng.']::text[]);

-- 66 ～に反して／～に反し／～に反する／～に反した
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('843e56f6-7498-5c28-91f3-e40bbd75e4f2', 0, 'Trái ngược với, ngược lại với ~.', ARRAY['人々の予想に反して、土地の値段が下がりつづけている。','弟は、親の期待に反することばかりしている。']::text[], ARRAY['Ngược với dự đoán của nhiều người, giá đất đang tiếp tục giảm.','Em tớ toàn làm những việc trái với mong đợi của bố mẹ.']::text[]);

-- 67 ～に基づいて／～に基づき／～に基づく／～に基づいた
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5f8e77a7-de5a-5b71-9b66-64e268f9c313', 0, 'Lấy ~ làm cơ sở, căn cứ vào ~ (tài liệu, sự việc có thật).', ARRAY['調査した資料に基づいて、レポートを書かなければならない。','実際にあった事件に基づき、この映画が作られた。']::text[], ARRAY['Cần phải viết báo cáo dựa trên các tư liệu đã điều tra.','Bộ phim này đã được làm ra dựa trên sự cố đã có trong thực tế.']::text[]);

-- 68 ～にわたって／～に渡り／～にわたる／～にわたった
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('32b4a3e9-e90d-50f9-826f-4daff0de76f9', 0, 'Biểu thị sự trải rộng trên phạm vi toàn thể, mang tính thời gian hoặc không gian.', ARRAY['西日本全域にわたり、台風の被害を受けた。','兄は5時間にわたる大手術を受けた。']::text[], ARRAY['Suốt cả vùng phía tây Nhật Bản đã gánh chịu sự phá hoại của bão.','Anh trai đã phải phẫu thuật trong suốt 5 giờ đồng hồ.']::text[]);

-- 69 ～ばかりか／～ばかりでなく
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('3fe7a7f3-f3ee-5c6c-b3cf-0bdef57d61c3', 0, 'Không chỉ ~, ngoài ra còn thêm ~ (thường ở mức độ gây bất ngờ hơn).', ARRAY['林さんのお宅でごちそうになったばかりか、おみやげまでいただいた。','彼はサッカーばかりでなく、水泳もダンスも上手なんですよ。']::text[], ARRAY['Ở nhà anh Hayashi, không chỉ được ăn ngon mà còn có quà mang về nữa.','Anh ấy không chỉ bóng đá mà còn bơi, nhảy đều giỏi.']::text[]);

-- 70 ～はもとより／～はもちろん
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('ad6d170d-972c-5c40-94f0-c91dc1e343d9', 0, '~ thì đương nhiên đến mức không cần nói, huống chi những cái khác cũng vậy.', ARRAY['私が生まれた村は、電車はもとより、バスも通っていない。','地震で被害を受けた人々の救援のために、医者はもとより、多くのボランティアも駆けつけた。']::text[], ARRAY['Ngôi làng mà tôi đã sinh ra thì xe điện là đương nhiên, xe buýt cũng không lưu thông.','Để cứu viện cho những người chịu thiệt hại của động đất, không chỉ bác sĩ mà nhiều tình nguyện viên cũng đã đến gấp.']::text[]);

-- 71 ～もかまわず
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('110dd542-cf98-5797-a447-02d58948b232', 0, 'Không bận tâm đến ~, dửng dưng không để ý đến ~.', ARRAY['人の迷惑もかまわず、電車の中で携帯電話で話している人がいる。','子供は服がぬれるのもかまわず、川の中に入って遊んでいる。']::text[], ARRAY['Không cần quan tâm đến việc làm phiền người khác, vẫn có người nói chuyện di động trong tàu điện.','Trẻ con không bận tâm đến quần áo bị ướt, đang nhảy xuống sông chơi.']::text[]);

-- 72 ～をこめて
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('8e54813b-653e-528d-ab40-34f6f73f3952', 0, 'Gửi gắm tâm tư, tình cảm vào ~.', ARRAY['母は私のために心をこめて、セーターを編んでくれた。','病気回復の祈りをこめて、みんなで鶴を折った。']::text[], ARRAY['Gửi gắm tất cả tình cảm của mình, mẹ đã đan cho tôi chiếc áo len.','Mọi người gấp hạc giấy gửi vào đó sự cầu mong được lành bệnh.']::text[]);

-- 73 ～を通じて／～を通して
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('d83478d4-31e5-526e-b3ee-96446f360edc', 0, 'Trong suốt khoảng thời gian đó, từ đầu đến cuối, liên tục.', ARRAY['あの地方は、1年を通じて雨が多い。','彼は一生を通して日本との友好のために働いた。']::text[], ARRAY['Ở địa phương đó, trong suốt năm mưa nhiều.','Ông ấy đã làm việc suốt đời vì tình hữu nghị với Nhật Bản.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('d83478d4-31e5-526e-b3ee-96446f360edc', 1, 'Không trực tiếp, thông qua một trung gian nào đó.', ARRAY['社長は忙しいから、秘書を通じて頼んだほうがいい。','今はインターネットを通して世界中の情報が手に入る。']::text[], ARRAY['Vì chủ tịch công ty bận, nên nhờ thông qua thư ký.','Bây giờ thông qua Internet mà có được thông tin của toàn thế giới.']::text[]);

-- 74 ～をめぐって／～をめぐる
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('f0bbd3b6-0f36-5982-b720-7aa48a97637d', 0, 'Nói về quan hệ xoay quanh, liên quan đến vấn đề trung tâm là ~.', ARRAY['その法案の賛否をめぐって、活発な議論が交わされた。','その事件をめぐって、様々なうわさが流れている。']::text[], ARRAY['Vì tán thành hay phủ quyết dự luật đó mà những thảo luận sôi nổi đã được trao đổi.','Có nhiều lời đồn quanh sự kiện đó.']::text[]);

-- 75 ～あまり
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5fd772ab-852e-500c-a46f-69576c71637c', 0, 'Vì ~ quá mức, bất thường nên dẫn đến một kết quả không mong muốn.', ARRAY['子供の将来を思うあまり、厳しすぎることを言ってしまった。','彼は働きすぎたあまり、過労で倒れてしまった。']::text[], ARRAY['Chỉ vì nghĩ đến tương lai của con mà tôi đã lỡ nói lời quá nghiêm khắc.','Làm việc quá nhiều nên anh ấy đã bất tỉnh vì quá sức.']::text[]);

-- 76 ～一方／～一方で（は）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('7742ff4b-2662-54c3-bed4-d52e66214d01', 0, 'Mặt khác, trái lại — thể hiện sự so sánh song song 2 mặt đối lập của cùng một sự việc.', ARRAY['私の仕事は夏は非常に忙しい一方、冬は暇になる。','地球上には豊かな人がいる一方では、明日の食べ物もない人がいる。']::text[], ARRAY['Công việc của tôi thì trái với mùa hè bận túi bụi, mùa đông lại nhàn hạ.','Trên thế giới có những người giàu, ngược lại cũng có những người không có cả thức ăn cho ngày mai.']::text[]);

-- 77 ～上で（は）／～上の／～上でも／～上での
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e4ca7e6a-87bb-5edd-97cb-4457b7320752', 0, 'Xong việc ~ rồi (mới làm gì tiếp theo, sau khi đã cân nhắc kỹ).', ARRAY['みんなの意見を聞いた上で決めました。','熟慮の上の結論です。']::text[], ARRAY['Nghe ý kiến của mọi người xong rồi quyết định.','Đây là kết luận sau khi đã cân nhắc kỹ lưỡng.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('e4ca7e6a-87bb-5edd-97cb-4457b7320752', 1, 'Dùng khi muốn nói trong phạm vi của thời điểm, hoàn cảnh, điều kiện đó.', ARRAY['日本の会社で働く上で、注意しなければならないことは何でしょうか。','酒の上でも、言ってはいけないことがある。']::text[], ARRAY['Làm việc trong xã hội Nhật Bản, điều cần chú ý là gì ạ?','Ngay cả lúc uống rượu, cũng có những điều không được nói.']::text[]);

-- 78 ～限り（は）／～かぎりでは／～ないかぎり（は）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('3f93139c-7329-5354-a390-fa53ab2e2d0b', 0, 'Trong khi/chừng nào vẫn còn trong tình trạng đó thì ~.', ARRAY['日本にいるかぎり、丹さんは私に連絡してくれるはずだ。','学生であるかぎり、勉強するのは当然だ。']::text[], ARRAY['Chừng nào còn ở Nhật, anh Đan chắc chắn sẽ liên lạc với tôi.','Còn là học sinh thì đương nhiên phải học rồi.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('3f93139c-7329-5354-a390-fa53ab2e2d0b', 1, 'Chỉ trong phạm vi thông tin/hiểu biết mà người nói có được.', ARRAY['私が知っているかぎりでは、この本は今年一番よく売れたそうです。','電話で話したかぎりでは、彼はそんなに怒っていませんでしたよ。']::text[], ARRAY['Trong phạm vi tôi được biết thì cuốn sách này nghe nói là được bán chạy nhất trong năm nay.','Cứ như nói chuyện trên điện thoại thì anh ấy không giận thế đâu.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('3f93139c-7329-5354-a390-fa53ab2e2d0b', 2, 'Cho đến giới hạn, hết mức có thể.', ARRAY['時間の許すかぎり、話し合いを続けましょう。','力のかぎり頑張ろう。']::text[], ARRAY['Trong giới hạn thời gian cho phép, chúng ta hãy tiếp tục trao đổi.','Hãy cố gắng hết sức!']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('3f93139c-7329-5354-a390-fa53ab2e2d0b', 3, 'Nếu điều kiện đó không xảy ra thì ~ (điều kiện phủ định).', ARRAY['雨や雪が降らないかぎり、毎日ジョギングを欠かさない。','魚は新鮮でないかぎり、刺身にはできない。']::text[], ARRAY['Nếu mưa hay tuyết không rơi, tôi sẽ không bỏ chạy hàng ngày.','Cá mà không tươi thì không làm món sashimi được.']::text[]);

-- 79 ～（か）と思うと／～（か）と思ったら
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('6c34ada8-0c7f-5d88-ac0a-17741abe020b', 0, 'Vừa mới ~ thì ngay lập tức đã ~ (thay đổi bất ngờ, nhanh chóng).', ARRAY['リーさんは「さようなら」と言ったかと思うと教室を飛び出していった。','空が暗くなったかと思ったら、大粒の雨が降ってきた。']::text[], ARRAY['Vừa thấy cô Lee nói "Sayounara" xong đã chạy biến ra khỏi phòng học.','Trời vừa tối đen cái là mưa như trút.']::text[]);

-- 80 ～か～ないかのうちに
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('342be15f-8a32-5ec9-930c-6a459f9eb1a7', 0, 'Việc trước chưa xong hẳn thì việc sau đã xảy ra ngay, gần như đồng thời.', ARRAY['ヘビースモーカーの彼は、タバコを1本吸い終わったか終わらないかのうちに、また次のタバコに火をつけた。','チャイムが鳴るか鳴らないかのうちに、先生が教室に入って来た。']::text[], ARRAY['Người nghiện thuốc nặng như anh ấy thì điếu này còn cháy dở đã châm điếu khác.','Chuông vừa reo chưa dứt, thầy giáo đã bước vào lớp.']::text[]);

-- 81 ～からいうと／～からいえば／～からいって
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('c50ccc0f-9ed1-5553-85bb-723d459aea5d', 0, 'Nhìn từ ~, xét theo tiêu chí/góc độ nào đó mà nói.', ARRAY['中国は人口からいうと世界一だが、人口密度は日本よりずっと低い。','実力からいって、彼女が入賞することは間違いない。']::text[], ARRAY['Trung Quốc nói về dân số thì đứng đầu thế giới, nhưng mật độ dân số thấp hơn Nhật nhiều.','Xét về thực lực mà nói, việc cô ấy nhận giải thưởng không có gì phải bàn cãi cả.']::text[]);

-- 82 ～からといって
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('5dc620c8-15c8-59d7-920d-a68535c83c66', 0, 'Chỉ vì lý do ~ thôi thì chưa chắc/không nhất thiết dẫn đến kết quả đó.', ARRAY['お金があるからといって偉いわけではない。','便利だからといって、機械に頼りすぎないようにしたい。']::text[], ARRAY['Chỉ vì có tiền thì không có nghĩa là người giỏi giang.','Tuy tiện lợi nhưng tôi vẫn không muốn dựa quá nhiều vào máy móc.']::text[]);

-- 83 ～から見ると／～から見れば／～から見て（も）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('d3204ecb-749b-5898-acd0-d8bb814f5bb2', 0, 'Nhìn từ ~, xét theo góc độ quan sát ~ mà đánh giá.', ARRAY['子供の教育という点からみると、豊かすぎる生活は、必ずしもいいとは言えない。','どこから見ても、あの人は紳士だ。']::text[], ARRAY['Nhìn từ quan điểm giáo dục trẻ em, chưa hẳn cuộc sống quá sung túc là tốt.','Dù theo khía cạnh nào, ông kia cũng là người lịch thiệp.']::text[]);

-- 84 ～きり（だ）
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('37845388-102d-5abb-a12e-8a60aa26ab74', 0, 'Chỉ có ~ mà thôi.', ARRAY['彼女は、何を聞いても笑っているきりで、答えない。','子供たちが独立してから、夫婦二人きりの生活です。']::text[], ARRAY['Cô ấy nghe gì cũng chỉ cười, chẳng đáp lại lời nào.','Con cái mà ra ở riêng, chỉ có hai vợ chồng sống với nhau.']::text[]);
insert into grammar_meanings (grammar_point_id, order_index, meaning_vi, examples_jp, examples_vi) values ('37845388-102d-5abb-a12e-8a60aa26ab74', 1, 'Trạng thái cứ thế tiếp diễn, không thay đổi kể từ đó.', ARRAY['寝たきり老人が増えている。','あの人は、アメリカへ行ったきりだ。']::text[], ARRAY['Người già ốm nằm liệt giường đang tăng lên.','Người kia đi Mỹ vẫn chưa về.']::text[]);

-- ============ grammar_points enrichment ============

update grammar_points set memory_tip = 'Vế trước là mục đích/tiêu chuẩn muốn đạt được, vế sau là hành động để đạt mục đích đó — luôn hình dung "làm sao để giống như vậy".', comparison_note = 'Khác ～ために (chỉ mục đích, đòi hỏi chủ ý mạnh, thường đi với động từ ý chí) — ～ように dùng được cả với động từ không ý chí như わかる、できる、なる.', common_mistake = 'Dùng ために sau động từ khả năng/vô ý chí (わかるために là sai, phải là わかるように).' where id = 'ee7e301d-9344-507b-925b-95e909465bd7';
update grammar_points set memory_tip = 'Chỉ dùng với động từ chỉ sự thay đổi theo một chiều (tăng/giảm/xấu đi...), không dùng với động từ tĩnh.', comparison_note = 'Khác ～一方で (nghĩa "mặt khác") — tuy viết giống nhau nhưng ～一方だ luôn diễn tả xu hướng một chiều liên tục, còn ～一方で so sánh hai mặt đối lập.', common_mistake = 'Nhầm hai mẫu ～一方だ và ～一方で vì cùng chữ 一方 — cần xem có "で" theo sau hay không để phân biệt nghĩa.' where id = '74403438-1728-5da6-aae7-216051b284ab';
update grammar_points set memory_tip = '恐れ vốn nghĩa là "sợ hãi" nên mẫu này luôn mang sắc thái tiêu cực, dự báo điều không tốt có thể xảy ra.', comparison_note = 'Khác ～かもしれない (khả năng chung chung, có thể tốt hoặc xấu) — ～おそれがある chỉ dùng cho việc xấu, thường trong văn phong trang trọng như tin tức, báo cáo.', common_mistake = 'Dùng ～おそれがある cho việc tốt (ví dụ 合格するおそれがある là sai vì đỗ là điều tốt, phải dùng かもしれない/はずだ).' where id = '0dc53113-6a7c-5cce-b145-edae7f422710';
update grammar_points set memory_tip = 'Nhớ nghĩa "đã được quyết định/quy định sẵn từ trước", không phải ý định của riêng cá nhân.', comparison_note = 'Khác ～ことにする (tự mình quyết định làm gì) — ～ことになっている là quy định/lịch trình đã có sẵn, mang tính khách quan hơn.', common_mistake = 'Dùng ～ことになっている khi nói về quyết định cá nhân nhất thời (phải dùng ～ことにする trong trường hợp đó).' where id = '917cc76e-220b-5483-bb52-d0c164e256cd';
update grammar_points set memory_tip = 'ことはない = "việc đó không tồn tại" nên suy ra "không cần thiết phải làm".', comparison_note = 'Khác ～なくてもいい (không cần làm cũng được, mang tính cho phép) — ～ことはない thường dùng để an ủi, khuyên đối phương đừng lo lắng/đừng làm quá.', common_mistake = 'Nhầm ～ことはない với ～ことがない (kinh nghiệm, "chưa từng") — hai mẫu nghĩa hoàn toàn khác nhau dù chỉ khác は/が.' where id = '62735d76-82f7-5e51-a68d-b559c3b527b9';
update grammar_points set memory_tip = 'しかない tự nó đã mang nghĩa phủ định ("chỉ ~ mà thôi, không còn gì khác") nên không cần thêm ない nữa.', comparison_note = 'Khác ～ほかない／～ほかしかたがない (nghĩa gần giống, trang trọng hơn) — ～しかない thông dụng hơn trong văn nói.', common_mistake = 'Chia động từ trước しかない ở thể ます (sai) — phải dùng thể từ điển (辞書形) + しかない.' where id = 'ed4c8c54-0f96-5d0c-8d1f-1c66a4904774';
update grammar_points set memory_tip = 'Nghĩa A (nghe nói) hay đi sau ～によると (theo như...); nghĩa B (tức là) dùng để diễn giải lại ý vừa nghe.', comparison_note = 'Khác ～そうだ (truyền văn, nghe nói) — ～ということだ trang trọng hơn, hay dùng trong văn viết/tin tức, còn そうだ tự nhiên hơn trong hội thoại.', common_mistake = 'Dùng ということだ (nghĩa nghe nói) mà không có nguồn tin rõ ràng (によると/では) khiến câu không tự nhiên.' where id = 'b5bf7b83-ce89-5b9e-a4bb-cff2490b208c';
update grammar_points set memory_tip = 'まい = "sẽ không...đâu" (phủ định ý chí/suy đoán) — là dạng cổ, trang trọng của ないだろう.', comparison_note = 'Khác ～ないだろう (suy đoán phủ định thông thường) — まい trang trọng, cứng nhắc hơn, thường dùng trong văn viết hoặc lời nói nghiêm túc.', common_mistake = 'Dùng まい cho chủ ngữ ngôi thứ 3 với nghĩa quyết tâm (B) — nghĩa quyết tâm chỉ dùng với chủ ngữ "tôi", ngôi 3 phải chuyển thành まいと思っているらしい.' where id = '9fad7ab0-1d4a-5af6-8365-914a013cad80';
update grammar_points set memory_tip = 'わけ vốn nghĩa "lý do, đạo lý" nên わけがない = "không có lý do/đạo lý nào cho việc đó" → khẳng định mạnh mẽ là không thể.', comparison_note = 'Khác ～はずがない (cũng phủ định mạnh nhưng dựa trên suy luận logic/thông tin có sẵn) — わけがない thiên về cảm nhận chủ quan, phán đoán từ thường thức.', common_mistake = 'Dùng わけがない cho sự việc chưa xảy ra trong tương lai xa (không tự nhiên) — mẫu này hợp với việc đang bị nghi ngờ ở hiện tại hơn.' where id = 'a639da1f-8b8f-5b2d-9751-786159697347';
update grammar_points set memory_tip = 'Luôn có lý do xã hội/đạo đức ràng buộc phía sau, không phải đơn thuần "không thể làm" về mặt vật lý.', comparison_note = 'Khác ～ことができない (không có khả năng làm) — わけにはいかない là "về lý mà nói thì không thể", dù bản thân có khả năng làm.', common_mistake = 'Dùng わけにはいかない cho việc bất khả thi về mặt vật lý (ví dụ 空を飛ぶわけにはいかない nghe kỳ — phải dùng ことができない).' where id = '256e8bf6-7e89-5cef-9b96-2ca27fcb4c93';
update grammar_points set memory_tip = 'Luôn đi theo cặp から～にかけて để chỉ phạm vi mờ, không xác định mốc kết thúc chính xác như まで.', comparison_note = 'Khác ～から～まで (phạm vi rõ ràng, có điểm đầu điểm cuối cụ thể) — にかけて mang tính ước lượng, mờ hơn.', common_mistake = 'Dùng にかけて khi cần nói mốc thời gian/địa điểm chính xác (phải dùng まで trong trường hợp đó).' where id = '81b0db01-98ae-5b1d-80c7-e5191aff4639';
update grammar_points set memory_tip = 'たとえ luôn đứng đầu câu, hô ứng với ても/でも ở cuối vế điều kiện — giống cặp "if...even" trong tiếng Anh.', comparison_note = 'Khác ～ても đơn thuần (nhượng bộ, không nhấn mạnh mức độ) — たとえ～ても nhấn mạnh tính cực đoan của giả định.', common_mistake = 'Quên đổi đuôi tính từ/danh từ cho đúng trước ても/でも (tính từ đuôi い→くても, tính từ な/danh từ→でも).' where id = '72fa61cf-d235-5ba7-9a95-783c9a4499a7';
update grammar_points set memory_tip = 'さえ luôn đi kèm một điều kiện ば/なら phía sau — chỉ cần thỏa điều kiện đó, mọi thứ khác coi như ổn.', comparison_note = 'Khác ～ば thông thường (điều kiện đơn) — さえ～ば nhấn mạnh đây là điều kiện tối thiểu, duy nhất cần có.', common_mistake = 'Quên chia đúng dạng ば cho từng loại từ (động từ ます形+さえすれば, tính từ い bỏ い+く+さえあれば...).' where id = '4486b45f-2f83-5c4e-bf43-1b73db957c34';
update grammar_points set memory_tip = 'Luôn liệt kê 2 việc cùng chiều (cùng tốt hoặc cùng xấu), không trộn lẫn 1 tốt 1 xấu.', comparison_note = 'Khác ～も～も (đơn giản chỉ nối 2 danh từ cùng loại) — ～も～ば～も cầu kỳ hơn, đòi hỏi vế đầu chia dạng ば/なら.', common_mistake = 'Trộn lẫn 1 điều tích cực với 1 điều tiêu cực trong cùng câu (không tự nhiên với mẫu này).' where id = 'd3c375f5-c444-52a2-bdea-bc03fb182ab2';
update grammar_points set memory_tip = 'やら～やら luôn cho cảm giác bề bộn, rối ren, liệt kê chưa hết còn nhiều việc khác nữa.', comparison_note = 'Khác ～や～など (liệt kê đơn thuần, trung tính) — やら～やら thường đi kèm cảm xúc mệt mỏi, bối rối của người nói.', common_mistake = 'Dùng やら～やら cho liệt kê trung tính, không có sắc thái mệt mỏi/bối rối (nên dùng や～など thay thế).' where id = '792bbf45-d4ab-59a2-a63a-5e1830d763e1';
update grammar_points set memory_tip = 'だらけ luôn mang nghĩa tiêu cực — bẩn, sai, xấu tràn lan khắp nơi trên bề mặt.', comparison_note = 'Khác ～まみれ (cũng nghĩa "đầy", nhưng nhấn mạnh chất lỏng/bụi bám dính lên người, ví dụ 汗まみれ) — だらけ dùng rộng hơn, kể cả lỗi sai, nợ nần.', common_mistake = 'Dùng だらけ cho điều tích cực (ví dụ 花だらけ nghe kỳ vì hoa không phải thứ xấu — nên dùng いっぱい thay vào).' where id = '79dfd539-f264-59f6-b1c4-f0f3fd3bb1df';
update grammar_points set memory_tip = 'っぽい gắn sau danh từ/tính từ (bỏ đuôi) để tạo tính từ mới nghĩa "có vẻ/hay".', comparison_note = 'Khác ～らしい (mang tính khách quan, đúng bản chất/tiêu chuẩn của loại đó) — っぽい thiên về cảm nhận chủ quan, đôi khi mang nghĩa "quá mức, hơi lố".', common_mistake = 'Dùng っぽい cho nhận xét trang trọng, lịch sự (sắc thái っぽい khá thân mật/hơi tiêu cực nên không hợp văn viết trang trọng).' where id = 'b18dba91-a707-501d-9c7c-11545cc0d4f2';
update grammar_points set memory_tip = 'がたい chỉ đi với động từ chỉ cảm xúc/tinh thần (信じる、忘れる、許す...) — không dùng cho khó khăn vật lý đơn thuần.', comparison_note = 'Khác ～にくい (khó làm về mặt vật lý/kỹ thuật, ví dụ 読みにくい字) — がたい nhấn mạnh khó khăn về mặt tâm lý, tình cảm.', common_mistake = 'Dùng がたい cho khó khăn vật lý đơn thuần như "chữ khó đọc" (phải dùng にくい, không dùng がたい).' where id = '87c3f6a3-91df-5663-92d5-4a49c80176ed';
update grammar_points set memory_tip = 'がち = "thường hay nghiêng về" một việc không mấy tốt đẹp — hay đi kèm 病気、休み、遅れる.', comparison_note = 'Khác ～気味 (chỉ trạng thái nhẹ, thoáng qua ở hiện tại) — がちだ chỉ tần suất lặp lại nhiều lần theo thời gian.', common_mistake = 'Nhầm がちだ (tần suất) với 気味 (trạng thái nhẹ hiện tại) — hai mẫu gần nghĩa nhưng không thay thế cho nhau hoàn toàn.' where id = '5f85e3b8-45e9-597a-a36e-c2e474a6655b';
update grammar_points set memory_tip = '気味 luôn ở mức độ nhẹ, thoáng qua — thường nói về sức khỏe, tâm trạng nhất thời.', comparison_note = 'Khác ～がちだ (chỉ tần suất lặp lại thường xuyên) — 気味 chỉ trạng thái ngay lúc nói, không nói về việc lặp lại nhiều lần.', common_mistake = 'Dùng 気味 cho trạng thái đã kéo dài, lặp lại nhiều lần (nên dùng がちだ trong trường hợp đó).' where id = '5fb295b1-250c-5589-9d92-113a71996c03';
update grammar_points set memory_tip = 'げ luôn miêu tả điều cảm nhận được từ vẻ bên ngoài người khác, không dùng để nói về bản thân mình.', comparison_note = 'Khác ～そうだ (suy đoán dựa trên vẻ ngoài, dùng được cho cả người và vật) — げ trang trọng/văn chương hơn, chủ yếu dùng cho tâm trạng con người.', common_mistake = 'Dùng げ để nói về cảm giác của chính mình (げ chỉ dùng để miêu tả người khác qua quan sát bên ngoài).' where id = '3849c416-5eaa-53c3-85ef-3b00b31965ef';
update grammar_points set memory_tip = 'かけ nghĩa gốc là "bắc cầu, treo lơ lửng" nên hành động đang treo lơ lửng giữa chừng, chưa xong.', comparison_note = 'Khác ～ている (đang tiếp diễn hành động) — かけ nhấn mạnh việc bị bỏ dở, dừng lại giữa chừng, chưa hoàn thành.', common_mistake = 'Dùng かけ cho hành động đang diễn ra bình thường không có ý dở dang (phải dùng ている trong trường hợp đó).' where id = '140f881f-f9a7-5fc5-9e1d-d656a31326b3';
update grammar_points set memory_tip = 'きる = "làm trọn vẹn, làm đến cùng"; thể khả năng きれる/きれない diễn tả có thể/không thể làm hết.', comparison_note = 'Khác ～ぬく (cũng nghĩa "làm đến cùng" nhưng nhấn mạnh sự kiên trì vượt khó khăn) — きる thiên về mức độ hoàn thành trọn vẹn.', common_mistake = 'Nhầm lẫn ý nghĩa きる (hoàn thành trọn vẹn) với ぬく (kiên trì vượt khó) khi dịch sang tiếng Việt đều là "đến cùng".' where id = '7789a2ae-6ab9-5f87-b72b-5804d8b8d670';
update grammar_points set memory_tip = 'ぬく hay đi với các động từ chỉ sự vất vả, gian nan (生きる、頑張る、考える) để nhấn mạnh kiên trì vượt qua.', comparison_note = 'Khác ～きる (nhấn mạnh hoàn thành trọn vẹn) — ぬく nhấn mạnh quá trình kiên trì, chịu đựng khó khăn đến cùng.', common_mistake = 'Dùng ぬく cho việc đơn giản không đòi hỏi nỗ lực (ぬく chỉ hợp với việc gian nan, vất vả).' where id = '52481372-d585-571e-b6eb-92a9bb273562';
update grammar_points set memory_tip = 'こそ đặt ngay sau từ cần nhấn mạnh — dịch là "chính là...".', comparison_note = 'Khác ～は (chủ đề trung tính) — こそ nhấn mạnh rõ ràng, đối lập với những lựa chọn khác.', common_mistake = 'Lạm dụng こそ trong văn nói thông thường khiến câu nghe quá gay gắt/trịnh trọng không cần thiết.' where id = '8461602d-154e-5ec3-b1b8-c5f5019c8e69';
update grammar_points set memory_tip = 'さえ lấy một ví dụ cực đoan để ngầm nói "còn những cái khác thì càng chắc chắn hơn".', comparison_note = 'Khác ～も (liệt kê đơn thuần) — さえ chọn trường hợp khó nhất/ít ngờ nhất để nhấn mạnh mức độ.', common_mistake = 'Quên bỏ trợ từ が/を khi gắn さえ vào danh từ (phải lược が/を, các trợ từ khác giữ nguyên).' where id = '77b4f91c-ed61-5c6a-a0ba-4642619e4072';
update grammar_points set memory_tip = 'など trang trọng, なんか/なんて thân mật hơn — cả ba đều dùng để hạ thấp/coi nhẹ mức độ quan trọng.', comparison_note = 'Khác ～や (liệt kê trung tính, không có sắc thái coi nhẹ) — など/なんか/なんて luôn mang ý khiêm tốn hoặc phủ định nhẹ.', common_mistake = 'Dùng など/なんか/なんて trong văn viết trang trọng (hai dạng なんか/なんて chỉ dùng trong hội thoại thân mật).' where id = 'ca07e76b-c745-54a5-be8a-efc20cbd1279';
update grammar_points set memory_tip = '関する khi bổ nghĩa cho danh từ (Nに関する話), 関して khi đứng giữa câu.', comparison_note = 'Khác ～について (cũng nghĩa "về việc gì" nhưng thông dụng, đời thường hơn) — に関して trang trọng hơn, hay dùng trong văn viết, báo cáo.', common_mistake = 'Dùng に関して cho chủ đề quá nhỏ nhặt, đời thường (nghe không tự nhiên, nên dùng について).' where id = '4ff96bde-949b-55f7-bde5-62010d6f9679';
update grammar_points set memory_tip = '加える nghĩa "thêm vào" nên に加えて = "ngoài A ra, còn thêm B nữa" (thường là 2 điều cùng gây khó khăn/tăng thêm).', comparison_note = 'Khác ～のほかに (cũng nghĩa "ngoài ra") — に加えて trang trọng hơn, hay dùng trong văn viết, tin tức.', common_mistake = 'Dùng に加えて cho 2 điều không liên quan đến nhau (mẫu này cần 2 điều cùng tính chất, cộng dồn tác động).' where id = 'b3743175-3ba4-55f2-b20c-41584e7e80aa';
update grammar_points set memory_tip = 'こたえる ở đây viết bằng hiragana, khác 答える (trả lời câu hỏi) dù cùng cách đọc — nghĩa là "đáp ứng, hồi đáp lại kỳ vọng/yêu cầu".', comparison_note = 'Khác ～に応じて (cũng nghĩa "tùy theo, đáp ứng theo" nhưng mang tính linh hoạt thay đổi theo hoàn cảnh) — にこたえて nhấn mạnh việc đáp lại đúng mong muốn/yêu cầu cụ thể.', common_mistake = 'Nhầm にこたえて (đáp ứng yêu cầu) với に答えて theo nghĩa "trả lời câu hỏi" thông thường trong ngữ cảnh phỏng vấn, khảo sát.' where id = 'b9855857-1ce7-53fa-80e1-e1b739a31536';
update grammar_points set memory_tip = '沿う nghĩa gốc là "đi dọc theo" (bờ sông, đường ray) nên nghĩa bóng là "làm đúng theo" phương châm, kế hoạch.', comparison_note = 'Khác ～に基づいて (căn cứ vào tài liệu/sự kiện có thật) — に沿って hay đi với phương châm, kế hoạch, nguyện vọng (thứ mang tính định hướng).', common_mistake = 'Nhầm lẫn に沿って với に基づいて khi cả hai đều dịch là "dựa trên/theo" — cần phân biệt danh từ đi sau là kế hoạch (沿って) hay dữ liệu thực tế (基づいて).' where id = 'dcc94866-8278-5fbc-9e5b-45d458fab014';
update grammar_points set memory_tip = '反する = "trái ngược, đi ngược lại" — hay đi với 予想、期待、意向 (những điều được mong đợi).', comparison_note = 'Khác ～に対して (chỉ đối tượng của hành động/thái độ, trung tính) — に反して luôn mang nghĩa trái ngược, đối lập.', common_mistake = 'Nhầm に反して với に対して chỉ vì phát âm gần giống nhau (反 han / 対 tai) — hai mẫu nghĩa khác hẳn nhau.' where id = '843e56f6-7498-5c28-91f3-e40bbd75e4f2';
update grammar_points set memory_tip = '基づく = "bắt nguồn từ, có căn cứ từ" — luôn đi sau danh từ chỉ tài liệu, sự kiện, kinh nghiệm có thật.', comparison_note = 'Khác ～に沿って (theo đúng phương châm/kế hoạch định hướng) — に基づいて nhấn mạnh căn cứ thực tế làm nền tảng.', common_mistake = 'Dùng に基づいて cho những thứ trừu tượng, không phải căn cứ cụ thể (như cảm xúc) — nên chọn mẫu khác trong trường hợp đó.' where id = '5f8e77a7-de5a-5b71-9b66-64e268f9c313';
update grammar_points set memory_tip = '渡る nghĩa gốc "băng qua, vượt qua" nên にわたって nhấn mạnh phạm vi rộng, kéo dài liên tục không ngắt quãng.', comparison_note = 'Khác ～中に (chỉ đơn thuần "trong khoảng thời gian đó") — にわたって nhấn mạnh mức độ rộng lớn, dài của phạm vi (nhiều năm, nhiều khu vực).', common_mistake = 'Dùng にわたって cho khoảng thời gian/phạm vi quá ngắn, nhỏ (mẫu này chỉ hợp khi phạm vi đủ lớn, đáng chú ý).' where id = '32b4a3e9-e90d-50f9-826f-4daff0de76f9';
update grammar_points set memory_tip = 'ばかりか/ばかりでなく = "không chỉ dừng ở A mà còn thêm B nữa", B thường ở mức độ ấn tượng hơn A.', comparison_note = 'Khác ～だけでなく (cũng nghĩa "không chỉ" nhưng trung tính, thông dụng hơn) — ばかりか/ばかりでなく trang trọng, hay dùng để nhấn mạnh sự bất ngờ.', common_mistake = 'Thêm の sau danh từ trước ばかりか (sai — danh từ đi trực tiếp không có の, khác với だけでなく).' where id = '3fe7a7f3-f3ee-5c6c-b3cf-0bdef57d61c3';
update grammar_points set memory_tip = 'もとより nghĩa gốc "từ đầu, vốn dĩ" nên はもとより = "cái đó thì đương nhiên khỏi cần nói, còn có thêm cả...".', comparison_note = 'Khác ～はもちろん (nghĩa giống hệt nhưng thông dụng, tự nhiên hơn trong cả nói và viết) — はもとより trang trọng hơn, thiên về văn viết.', common_mistake = 'Dùng はもとより trong hội thoại thân mật hàng ngày (nghe cứng nhắc — nên dùng はもちろん cho tự nhiên hơn).' where id = 'ad6d170d-972c-5c40-94f0-c91dc1e343d9';
update grammar_points set memory_tip = '構う nghĩa "bận tâm, để ý" nên もかまわず = "không thèm để ý/bận tâm đến..." mang sắc thái phê phán nhẹ.', comparison_note = 'Khác ～も気にせず (cũng nghĩa tương tự nhưng trung tính hơn) — もかまわず thường mang hàm ý người nói không đồng tình với thái độ đó.', common_mistake = 'Dùng もかまわず cho hành động đáng khen (mẫu này thường đi kèm sắc thái hơi tiêu cực/đáng trách).' where id = '110dd542-cf98-5797-a447-02d58948b232';
update grammar_points set memory_tip = '込める nghĩa "dồn vào, gửi gắm vào" — luôn đi với danh từ chỉ tình cảm (心、愛、祈り、感謝).', comparison_note = 'Khác ～で (phương tiện đơn thuần) — をこめて nhấn mạnh yếu tố tình cảm, tâm huyết gửi gắm vào hành động.', common_mistake = 'Dùng をこめて cho vật/hành động không liên quan cảm xúc (mẫu này chỉ hợp khi có yếu tố tình cảm rõ ràng).' where id = '8e54813b-653e-528d-ab40-34f6f73f3952';
update grammar_points set memory_tip = '通す nghĩa "xuyên suốt, đi qua" — nghĩa A là "xuyên suốt thời gian", nghĩa B là "thông qua trung gian".', comparison_note = 'Khác ～によって (chỉ phương tiện/nguyên nhân đơn thuần) — を通じて／を通して nhấn mạnh yếu tố trung gian kết nối hai phía.', common_mistake = 'Nhầm lẫn giữa nghĩa A (xuyên suốt thời gian) và nghĩa B (qua trung gian) của cùng một mẫu khi dịch sang tiếng Việt.' where id = 'd83478d4-31e5-526e-b3ee-96446f360edc';
update grammar_points set memory_tip = '巡る nghĩa gốc "đi vòng quanh" nên をめぐって = "xoay quanh vấn đề đó" (tranh luận, tranh chấp, tin đồn).', comparison_note = 'Khác ～について (nói về chủ đề gì đó, trung tính) — をめぐって luôn hàm ý có tranh luận, ý kiến trái chiều xoay quanh chủ đề đó.', common_mistake = 'Dùng をめぐって cho chủ đề không có tranh cãi/ý kiến trái chiều (nên dùng について thay vào cho tự nhiên).' where id = 'f0bbd3b6-0f36-5982-b720-7aa48a97637d';
update grammar_points set memory_tip = '余り nghĩa gốc "phần dư ra" nên あまり = "vì mức độ vượt quá giới hạn bình thường" nên dẫn đến kết quả không mong muốn.', comparison_note = 'Khác ～すぎて (cũng nghĩa "quá mức" nhưng thông dụng, trung tính hơn) — あまり trang trọng hơn và luôn dẫn đến kết quả tiêu cực, bất thường.', common_mistake = 'Dùng あまり cho kết quả tích cực, bình thường (mẫu này chỉ hợp với kết quả tiêu cực/bất ngờ).' where id = '5fd772ab-852e-500c-a46f-69576c71637c';
update grammar_points set memory_tip = 'Luôn so sánh 2 mặt đối lập của cùng một sự vật/hiện tượng, không phải 2 sự việc không liên quan.', comparison_note = 'Khác ～一方だ (chỉ xu hướng một chiều liên tục tăng/giảm) — ～一方で so sánh song song hai khía cạnh khác nhau.', common_mistake = 'Nhầm ～一方で (so sánh hai mặt) với ～一方だ (xu hướng một chiều) vì viết gần giống — chú ý có vế so sánh đi kèm hay không.' where id = '7742ff4b-2662-54c3-bed4-d52e66214d01';
update grammar_points set memory_tip = '上で nghĩa A đi sau động từ thể た (đã xong việc gì rồi mới...); nghĩa B đi sau danh từ/động từ từ điển (trong phạm vi đó).', comparison_note = 'Khác ～てから (chỉ đơn thuần thứ tự trước-sau, trung tính) — 上で nhấn mạnh việc B là bước quan trọng, cần thiết sau khi hoàn thành A.', common_mistake = 'Nhầm 上で (sau khi làm xong) với 上に (thêm vào đó) — hai mẫu viết gần giống nhưng nghĩa khác hẳn nhau.' where id = 'e4ca7e6a-87bb-5edd-97cb-4457b7320752';
update grammar_points set memory_tip = '4 nghĩa của 限り xoay quanh ý gốc "giới hạn": còn trong giới hạn đó (A), trong phạm vi biết được (B), đến giới hạn tối đa (C), nếu giới hạn đó không bị phá vỡ tức là "nếu không" (D).', comparison_note = 'Khác ～なければ (điều kiện phủ định đơn thuần) — ～ないかぎり nhấn mạnh đây là điều kiện tiên quyết duy nhất, khó thay đổi.', common_mistake = 'Nhầm lẫn giữa 4 nghĩa của 限り do cùng một từ nhưng cấu trúc khác nhau (đặc biệt dễ nhầm A và D vì cùng đứng sau động từ).' where id = '3f93139c-7329-5354-a390-fa53ab2e2d0b';
update grammar_points set memory_tip = 'Vế trước luôn ở thể た, diễn tả 2 sự việc xảy ra gần như ngay lập tức nối tiếp nhau, thường gây bất ngờ.', comparison_note = 'Khác ～たら thông thường (điều kiện/thời gian đơn thuần) — と思うと／と思ったら nhấn mạnh sự bất ngờ, nhanh chóng của việc tiếp theo.', common_mistake = 'Dùng mẫu này cho ý định/kế hoạch tương lai (mẫu chỉ dùng để kể lại việc đã xảy ra trong quá khứ, không dùng cho tương lai).' where id = '6c34ada8-0c7f-5d88-ac0a-17741abe020b';
update grammar_points set memory_tip = 'Lặp lại cùng một động từ ở dạng khẳng định và phủ định (Vか Vないかのうちに) để nhấn mạnh việc thứ 2 xảy ra gần như cùng lúc, chưa kịp xong việc 1.', comparison_note = 'Khác ～たととんに (ngay khi vừa xong việc 1, việc 1 đã hoàn tất) — ～か～ないかのうちに nhấn mạnh việc 1 chưa xong hẳn mà việc 2 đã xảy ra.', common_mistake = 'Dùng hai động từ khác nhau ở hai vế (sai cấu trúc — phải lặp lại cùng một động từ ở cả hai vế).' where id = '342be15f-8a32-5ec9-930c-6a459f9eb1a7';
update grammar_points set memory_tip = '言う ở đây không phải "nói" theo nghĩa đen mà là "xét theo góc độ/quan điểm nào đó mà nói".', comparison_note = 'Khác ～から見ると (cũng nghĩa "xét theo" nhưng thiên về quan sát bề ngoài) — からいうと thiên về lập luận, đánh giá dựa trên tiêu chí cụ thể (thực lực, chất lượng...).', common_mistake = 'Nhầm lẫn からいうと với から見ると khi cả hai đều dịch "xét theo" — cần chú ý danh từ đi trước là tiêu chí đánh giá hay là ấn tượng quan sát.' where id = 'c50ccc0f-9ed1-5553-85bb-723d459aea5d';
update grammar_points set memory_tip = 'Luôn đi kèm về sau một mệnh đề phủ định hoặc ý "không hẳn/chưa chắc" — bác bỏ suy luận logic đơn giản từ lý do đó.', comparison_note = 'Khác ～から (lý do đơn thuần, dẫn đến kết quả logic) — ～からといって phủ nhận mối liên hệ logic tất yếu giữa lý do và kết quả.', common_mistake = 'Dùng ～からといって mà vế sau lại là câu khẳng định thông thường (mẫu này cần vế sau mang tính bác bỏ/phủ định suy luận).' where id = '5dc620c8-15c8-59d7-920d-a68535c83c66';
update grammar_points set memory_tip = '見る ở đây nghĩa "quan sát, đánh giá" nên から見ると = "nhìn/quan sát từ góc độ đó mà đánh giá".', comparison_note = 'Khác ～からいうと (thiên về lập luận dựa trên tiêu chí cụ thể) — から見ると thiên về ấn tượng, cảm nhận qua quan sát bề ngoài.', common_mistake = 'Nhầm lẫn から見ると với からいうと do cùng dịch "xét theo" — から見ると hợp khi nói về vẻ ngoài/biểu hiện quan sát được (dáng vẻ, thái độ).' where id = 'd3204ecb-749b-5898-acd0-d8bb814f5bb2';
update grammar_points set memory_tip = 'Nghĩa A (chỉ có) đi sau danh từ/động từ từ điển; nghĩa B (trạng thái tiếp diễn không đổi) đi sau động từ thể た.', comparison_note = 'Khác ～だけ (cũng nghĩa "chỉ có" nhưng trung tính, không có sắc thái) — きり ở nghĩa B còn mang ý tiếc nuối vì trạng thái không thay đổi kể từ đó.', common_mistake = 'Nhầm hai nghĩa của きり do cùng một từ — cần xem động từ đi trước là thể từ điển (nghĩa A: chỉ có) hay thể た (nghĩa B: cứ thế không đổi).' where id = '37845388-102d-5abb-a12e-8a60aa26ab74';
